sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type, void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    struct sctp_chunk *chunk = (struct sctp_chunk *)arg;

    if (!chunk || chunk->chunk_hdr->type != type)
        return SCTP_DISPOSITION_NOMEM;

    /* Increment statistics for processing out-of-band chunk */
    SCTP_INC_STATS(net, SCTP_MIB_OOBCHECK);

    /* Validate chunk length */
    if (chunk->chunk_end - chunk->chunk_start < sizeof(sctp_chunkhdr_t))
        return SCTP_DISPOSITION_BAD;

    switch (chunk->chunk_hdr->type) {
    case SCTP_CID_SHUTDOWN_ACK:
        sctp_add_cmd(commands, SCTP_CMD_SHUTDOWN_ACK_RECEIVED, NULL);
        break;
    case SCTP_CID_ABORT:
        sctp_add_cmd(commands, SCTP_CMD_ABORT_ASSOC, NULL);
        break;
    case SCTP_CID_COOKIE_ACK:
        sctp_add_cmd(commands, SCTP_CMD_COOKIE_ACK_RECEIVED, NULL);
        break;
    default:
        disposition = SCTP_DISPOSITION_DISCARD;
        break;
    }

    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment statistics */
    net->sctp.statistics[SctpOutOfBlue]++;

    if (!sctp_chunk_length_valid(chunk)) {
        net->sctp.statistics[SctpInvalidChunk]++;
        return SCTP_DISPOSITION_DISCARD;
    }

    if (SCTP_CHUNK_IS_SHUTDOWN_ACK(chunk)) {
        sctp_cmd_seq_t temp_commands;
        sctp_process_shutdown_ack(net, ep, asoc, chunk, &temp_commands);
        sctp_cmd_seq_merge(commands, &temp_commands);
    } else if (SCTP_CHUNK_IS_ABORT(chunk)) {
        sctp_cmd_seq_t temp_commands;
        sctp_process_abort(net, ep, asoc, chunk, &temp_commands);
        sctp_cmd_seq_merge(commands, &temp_commands);
        disposition = SCTP_DISPOSITION_ABORT;
    } else if (SCTP_CHUNK_IS_COOKIE_ACK(chunk)) {
        sctp_cmd_seq_t temp_commands;
        sctp_process_cookie_ack(net, ep, asoc, chunk, &temp_commands);
        sctp_cmd_seq_merge(commands, &temp_commands);
    } else {
        net->sctp.statistics[SctpUnrecognizedChunk]++;
        disposition = SCTP_DISPOSITION_DISCARD;
    }

    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment the appropriate SCTP statistics */
    net->sctp.statistics.oob_chunks_received++;

    /* Validate the chunk length */
    if (sctp_chunk_length_invalid(arg)) {
        /* Handle invalid chunk length */
        net->sctp.statistics.invalid_oob_chunks++;
        return SCTP_DISPOSITION_NOREPLY;
    }

    /* Check for specific chunk types and handle accordingly */
    if (SCTP_CHUNK_TYPE(type) == SCTP_SHUTDOWN_ACK) {
        sctp_handle_shutdown_ack(net, ep, asoc, commands);
    } else if (SCTP_CHUNK_TYPE(type) == SCTP_ABORT) {
        sctp_handle_abort(net, ep, asoc, commands);
    } else if (SCTP_CHUNK_TYPE(type) == SCTP_COOKIE_ACK) {
        sctp_handle_cookie_ack(net, ep, asoc, commands);
    } else {
        /* If the chunk type is not recognized, discard the packet */
        net->sctp.statistics.unknown_oob_chunks++;
        disposition = SCTP_DISPOSITION_DISCARD;
    }

    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    struct sctp_chunk *chunk = (struct sctp_chunk *)arg;

    SCTP_INC_STATS(SCTP_MIB_IN_PKT_SOFTERRORS);

    if (!sctp_chunk_length_valid(chunk)) {
        sctp_chunk_free(chunk);
        return SCTP_DISPOSITION_DISCARD;
    }

    switch (chunk->type) {
    case SCTP_CHUNK_TYPE_SHUTDOWN_ACK:
        sctp_handle_shutdown_ack(net, ep, asoc, chunk, commands);
        break;
    case SCTP_CHUNK_TYPE_ABORT:
        sctp_handle_abort(net, ep, asoc, chunk, commands);
        disposition = SCTP_DISPOSITION_ABORT;
        break;
    case SCTP_CHUNK_TYPE_COOKIE_ACK:
        sctp_handle_cookie_ack(net, ep, asoc, chunk, commands);
        break;
    default:
        disposition = SCTP_DISPOSITION_DISCARD;
        break;
    }

    return disposition;
}

sctp_disposition_t sctp_process_oob_chunk(struct net *net,
                                          const struct sctp_endpoint *ep,
                                          const struct sctp_association *asoc,
                                          sctp_subtype_t type,
                                          void *arg,
                                          sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    /* Increment the appropriate statistics */
    net->sctp_statistics->sctpOutCtrlChunks++;

    /* Validate the chunk length */
    if (chunk->chunk_hdr->length < sizeof(sctp_chunkhdr_t)) {
        /* Invalid chunk length, discard the packet */
        return SCTP_DISPOSITION_DISCARD;
    }

    /* Check the chunk type and handle accordingly */
    switch (chunk->chunk_hdr->type) {
    case SCTP_CID_SHUTDOWN_ACK:
        if (asoc->state == SCTP_STATE_SHUTDOWN_PENDING) {
            sctp_send_shutdown_complete(net, ep, asoc);
        }
        break;

    case SCTP_CID_ABORT:
        sctp_handle_abort(net, ep, asoc, chunk);
        disposition = SCTP_DISPOSITION_ABORT;
        break;

    case SCTP_CID_COOKIE_ACK:
        if (asoc->state == SCTP_STATE_COOKIE_ECHOED) {
            sctp_send_state_cookie(net, ep, asoc);
            disposition = SCTP_DISPOSITION_DELETE_TCB;
        }
        break;

    default:
        /* Unsupported or irrelevant chunk type */
        break;
    }

    /* Add any necessary commands to the command sequence */
    if (commands) {
        sctp_cmd_seq_add(commands, SCTP_CMD_ECHO, chunk);
    }

    return disposition;
}
